package com.example.grafanapocket;

import android.app.*;import android.appwidget.AppWidgetManager;import android.content.*;import android.os.Bundle;import android.view.View;import android.widget.*;import org.json.*;import java.net.URLEncoder;import java.util.*;

public class WidgetConfigActivity extends Activity {
    int widgetId,loadGeneration;Spinner connection,panel;EditText from,to;TextView status;Button save;List<Connection> items;final List<String> panelIds=new ArrayList<>();
    @Override public void onCreate(Bundle b){super.onCreate(b);setResult(RESULT_CANCELED);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);items=new SecureStore(this).all();
        LinearLayout root=Ui.column(this);Ui.fill(root,Ui.title(this,"配置 Grafana 小组件"));TextView hostLabel=Ui.title(this,"1. 选择已添加的远程主机");hostLabel.setTextSize(15);Ui.fill(root,hostLabel);connection=new Spinner(this);List<String> names=new ArrayList<>();for(Connection c:items)names.add(c.name);connection.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));Ui.fill(root,connection);
        TextView panelLabel=Ui.title(this,"2. 选择 Dashboard 数据窗口");panelLabel.setTextSize(15);Ui.fill(root,panelLabel);panel=new Spinner(this);Ui.fill(root,panel);status=Ui.title(this,"请选择远程主机");status.setTextSize(13);Ui.fill(root,status);Button retry=Ui.button(this,"重新读取面板列表");retry.setOnClickListener(v->loadPanels());Ui.fill(root,retry);
        from=Ui.input(this,"起始时间，例如 now-6h");to=Ui.input(this,"结束时间，例如 now");from.setText("now-6h");to.setText("now");Ui.fill(root,from);Ui.fill(root,to);save=Ui.button(this,"添加小组件");save.setEnabled(false);save.setOnClickListener(v->save());Ui.fill(root,save);
        if(items.isEmpty()){status.setText("请先在 App 中添加 Grafana 连接。");connection.setEnabled(false);}else connection.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){loadPanels();}public void onNothingSelected(AdapterView<?> p){}});
        ScrollView s=new ScrollView(this);s.addView(root);setContentView(s);
    }
    void loadPanels(){if(items.isEmpty())return;int generation=++loadGeneration;Connection c=items.get(connection.getSelectedItemPosition());status.setText("正在从 "+c.name+" 读取面板…");save.setEnabled(false);panelIds.clear();panel.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"正在读取…"}));new Thread(()->{try{String uid=GrafanaApi.uid(c.dashboard);if(uid.isEmpty())throw new Exception("Dashboard 路径中没有 UID，请使用 /d/UID/名称");JSONObject response=new JSONObject(GrafanaApi.get(c,"/api/dashboards/uid/"+URLEncoder.encode(uid,"UTF-8")));List<JSONObject> found=new ArrayList<>();PanelSelectionActivity.collect(response.getJSONObject("dashboard").optJSONArray("panels"),found);List<String> labels=new ArrayList<>(),ids=new ArrayList<>();labels.add("完整 Dashboard");ids.add("");for(JSONObject p:found){int id=p.optInt("id",-1);if(id<0)continue;labels.add(p.optString("title","未命名窗口")+"  ·  "+p.optString("type")+"  ·  ID "+id);ids.add(String.valueOf(id));}runOnUiThread(()->{if(generation!=loadGeneration)return;panelIds.clear();panelIds.addAll(ids);panel.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));status.setText("已读取 "+found.size()+" 个数据窗口");save.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{if(generation==loadGeneration)status.setText(e.getMessage());});}}).start();}
    void save(){if(panelIds.isEmpty())return;Connection c=items.get(connection.getSelectedItemPosition());String selected=panelIds.get(panel.getSelectedItemPosition());getSharedPreferences("widgets",MODE_PRIVATE).edit().putString("connection_"+widgetId,c.id).putString("path_"+widgetId,c.dashboard).putString("panel_"+widgetId,selected).putString("from_"+widgetId,from.getText().toString()).putString("to_"+widgetId,to.getText().toString()).apply();WidgetUpdateJobService.schedule(this);GrafanaWidgetProvider.update(this,AppWidgetManager.getInstance(this),widgetId);Intent result=new Intent();result.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId);setResult(RESULT_OK,result);finish();}
}
